#!/usr/bin/env python3
"""Extracts the pure file helpers from util/ShellClient.kt.

ShellClient.kt is a 657-line orchestration object. The top of the file holds transport-free
helpers: the file-edit matcher/replacer, line counting, SHA-256 and the bounded shell-output
reader. This extractor copies those declarations verbatim; only the three private helpers are
widened to internal so the golden driver can call them.

Usage: python3 extract_shell_file_edit.py <ShellClient.kt> <out.kt>
"""
import os
import sys

HEADER = """\
// GENERATED by extract_shell_file_edit.py -- do not edit.
//
// Pure file helpers copied verbatim from util/ShellClient.kt. The three private helpers were
// widened to internal so the golden driver can call them; every declaration is otherwise
// byte-identical to the app source.
package com.newoether.agora.util

import java.io.ByteArrayOutputStream
import java.io.InputStream

"""

TARGETS = [
    ("internal const val SHELL_COMMAND_OUTPUT_MAX_BYTES", "line"),
    ("data class ShellFileReadResult(", "data"),
    ("data class ShellFileEditResult(", "data"),
    ("internal fun shellFileLineCount(", "function"),
    ("internal fun InputStream.readBoundedShellOutput(", "function"),
    ("private fun completeUtf8PrefixLength(", "function"),
    ("internal fun fileEditMatchRanges(", "function"),
    ("internal fun replaceFileEditMatches(", "function"),
    ("internal fun editShellFileContent(", "function"),
    ("internal fun shellFileSha256(", "function"),
    ("private fun preferredFileEditLineEnding(", "function"),
    ("private fun String.withFileEditLineEnding(", "function"),
]


def find_start(lines, marker):
    for index, line in enumerate(lines):
        if line.startswith(marker):
            return index
    raise SystemExit(f"error: marker not found: {marker}")


def extract_data(lines, marker):
    start = find_start(lines, marker)
    for index in range(start, len(lines)):
        if lines[index].rstrip() == ")":
            return lines[start:index + 1]
    raise SystemExit(f"error: closing parenthesis not found for {marker}")


def extract_function(lines, marker):
    start = find_start(lines, marker)
    depth = 0
    seen_open = False
    for index in range(start, len(lines)):
        depth += lines[index].count("{") - lines[index].count("}")
        if "{" in lines[index]:
            seen_open = True
        if seen_open and depth <= 0:
            return lines[start:index + 1]
    raise SystemExit(f"error: closing brace not found for {marker}")


def main():
    if len(sys.argv) != 3:
        raise SystemExit(__doc__)
    source_path, out_path = sys.argv[1], sys.argv[2]
    with open(source_path) as handle:
        lines = handle.read().splitlines(keepends=True)

    blocks = []
    for marker, kind in TARGETS:
        if kind == "data":
            block = extract_data(lines, marker)
        elif kind == "line":
            block = [lines[find_start(lines, marker)]]
        else:
            block = extract_function(lines, marker)
        block = [line.replace("private fun", "internal fun", 1) for line in block]
        blocks.append("".join(block).rstrip() + "\n")

    parent = os.path.dirname(out_path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(out_path, "w") as handle:
        handle.write(HEADER)
        handle.write("\n\n".join(blocks))
        handle.write("\n")
    print(f"extracted {sum(len(block.splitlines()) for block in blocks)} lines into {out_path}")


if __name__ == "__main__":
    main()
